"""Canonical transport-first preview. Original migration is retained in Git history."""
from pathlib import Path
import html
import json

ROOT = Path(__file__).resolve().parents[1]
VERSION = '20261021-image-actions'
CONTENT = json.loads((ROOT/'scripts/transport-content.json').read_text(encoding='utf8'))
NAV = [('', 'Home'), ('trucking-for-hire', 'Fuel Transport'), ('about', 'Our Story'),
       ('employment-opportunities', 'Careers'), ('contact', 'Contact & Dispatch')]


def photo(file, alt, caption='', cls=''):
    return f'<figure class="transport-photo riveted-photo {cls}"><img src="@assets/{file}" alt="{html.escape(alt)}" loading="lazy" decoding="async">'+(f'<figcaption>{caption}</figcaption>' if caption else '')+'</figure>'


def action(href, label):
    return f'<a class="transport-button office-call-choice" href="{href}">{label}</a>'


def art(href, file, label, cls=''):
    dimensions = {'put-us-to-work.jpg': (1024,499), 'check-out-our-fleet.jpg': (1024,254), 'call-dispatch.jpg': (1024,684), 'main-office.jpg': (1024,757), 'email-dispatch.jpg': (1024,757), 'directions.jpg': (1024,415), 'pacific-pride.jpg': (1024,433), 'credit-app.jpg': (1024,432), 'ask-our-team.jpg': (1024,397), 'talk-to-rinehart.jpg': (488,141)}
    width, height = dimensions[file]
    return f'<a class="history-card transport-art-button {cls}" href="{html.escape(href, quote=True)}" aria-label="{html.escape(label, quote=True)}"><img src="@assets/{file}" alt="{html.escape(label, quote=True)}" width="{width}" height="{height}" loading="lazy" decoding="async"></a>'


def intro(kicker, title, text):
    return f'<section class="transport-intro"><p class="eyebrow">{kicker}</p><h1>{title}</h1><p class="intro-text">{text}</p></section>'


def fleet():
    images = [('6346-rino-truck-6-1-of-1-cropped.webp', 'Rinehart truck and tank trailer'),
              ('6338-rino-truck-4-1-of-1.webp', 'Rinehart tanker fleet at the yard'),
              ('owner-07.webp', 'Rinehart number 22 fuel delivery truck'),
              ('owner-11.webp', 'Rinehart number 23 tanker and trailer')]
    visible = '<div class="transport-gallery">'+''.join(photo(f, a, a) for f, a in images[:2])+'</div>'
    more = '<details class="contact-disclosure transport-more-fleet"><summary>More Fleet Photos</summary><div class="transport-disclosure-body transport-gallery">'+''.join(photo(f, a, a) for f, a in images[2:])+'</div></details>'
    return visible+more


def shell(title, slug, body, cta=False):
    prefix = '../' if slug else ''
    nav = ''.join(f'<a href="{prefix}{s+"/" if s else ""}index.html"'+(' aria-current="page"' if s == slug else '')+f'>{label}</a>' for s, label in NAV)
    bottom = '''<section class="bottom-cta"><div class="cta-panel"><div><p class="eyebrow">A REAL TEAM. A RELIABLE PARTNER.</p><h2>Let’s Keep You Moving.</h2></div><a class="contact-image-button" href="@contact/index.html"><img src="@assets/talk-to-rinehart.jpg" alt="Talk To Rinehart" width="488" height="141" loading="lazy"></a></div></section>''' if cta else ''
    text = f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>{title} | Rinehart Oil</title><meta name="description" content="Family-owned fuel transportation for wholesalers, major oil companies and retail chains. Contact Rinehart Oil’s transport team in Ukiah, California."><link rel="icon" href="@assets/rino-logo-transparent.png" type="image/png"><link rel="stylesheet" href="@assets/site.css?v={VERSION}"><link rel="stylesheet" href="@assets/transport.css?v={VERSION}"><script defer src="@assets/site.js?v={VERSION}"></script></head><body class="transport-site"><a class="skip" href="#main">Skip To Content</a><header><div class="masthead"><a class="brand" href="@index.html" aria-label="Rinehart Oil Home"><img class="rino-logo" src="@assets/rino-logo-transparent.png" alt="RINO, Rinehart Oil Inc." width="330" height="110"><small>FAMILY OWNED. ROAD PROVEN.</small></a><a class="phone" href="tel:+17074673313"><small>DISPATCH</small>(707) 467-3313</a><button class="menu" aria-expanded="false" aria-controls="nav">Menu</button></div><nav id="nav">{nav}</nav></header><main id="main" class="transport-main">{body}</main>{bottom}<footer><div class="transport-footer-brand"><a class="brand footer-brand" href="@index.html" aria-label="Rinehart Oil Home"><img class="rino-logo" src="@assets/rino-logo-transparent.png" alt="RINO, Rinehart Oil Inc." width="180" height="60" loading="lazy"></a><p>Family Owned. Road Proven. Since 1959.</p><p>2401 N. State Street, Ukiah, CA 95482<br>P.O. Box 725, Ukiah, CA 95482</p></div><div class="transport-footer-contact"><a href="tel:+17074673313"><strong>Dispatch:</strong> <span class="transport-number">(707) 467-3313</span></a><a href="mailto:dispatch@rinehartoil.com">dispatch@rinehartoil.com</a><a href="tel:+17074628811"><strong>Office:</strong> <span class="transport-number">(707) 462-8811</span></a></div><div class="transport-footer-links"><a href="@trucking-for-hire/index.html#fleet">Our Fleet</a><a href="@employment-opportunities/index.html">Careers</a><a href="@pacific-pride-card-lock/index.html">Existing Cardlock Customers</a><a href="https://app.testteamtrainer.com/" rel="noopener noreferrer">Employee Training</a></div><div class="footer-base"><span>© 2026 Rinehart Oil, Inc. <a href="@privacy-policy/index.html">Privacy</a></span></div></footer></body></html>'''
    for target in ('assets/', 'contact/', 'index.html', 'trucking-for-hire/', 'about/', 'employment-opportunities/', 'pacific-pride-card-lock/', 'privacy-policy/'):
        text = text.replace('@'+target, prefix+target)
    return text


def build():
    home = '''<section class="transport-home-hero"><div class="transport-hero-copy"><p class="eyebrow">FUEL TRANSPORT. FAMILY OWNED. SINCE 1959.</p><h1>Built To Deliver.<br>Driven By Service.</h1><p class="transport-lead">Your Fuel. Our Commitment.</p><p>Fuel hauling for wholesalers, major oil companies and retail chains. A company-owned fleet and a team you can reach directly.</p><div class="transport-actions">'''+action('@contact/index.html', 'Discuss Your Transport Needs')+'''<a class="transport-text-link" href="tel:+17074673313">Dispatch: (707) 467-3313</a></div></div>'''+photo('6374-truck-gg-bridge.webp', 'Rinehart fuel tanker with the Golden Gate Bridge', cls='transport-hero-photo')+'''</section><section class="transport-section" id="services"><h2>Built Around Your Delivery.</h2><div class="transport-capabilities"><div><h3>For Wholesalers</h3><p>Fuel transportation to support your customers and delivery schedule.</p></div><div><h3>For Major Oil Companies</h3><p>Company-owned equipment and direct coordination with our team.</p></div><div><h3>For Retail Chains</h3><p>Fuel hauling for the stations and locations your business serves.</p></div></div></section><section class="transport-home-fleet transport-section">'''+photo('6346-rino-truck-6-1-of-1-cropped.webp', 'Rinehart red and white tanker truck and trailer')+'''<div><p class="eyebrow">OUR EQUIPMENT. OUR RESPONSIBILITY.</p><h2>Company Owned.<br>Customer Driven.</h2><p>Meet the fleet behind the delivery and talk with our team about your next load.</p><a class="transport-text-link" href="@trucking-for-hire/index.html#fleet">Explore Fuel Transport &amp; Our Fleet</a><div class="transport-heritage"><h3>A Family Business Since 1959.</h3><p>The Rinehart name has grown through generations of work in the fuel industry.</p><a class="history-card transport-history-button" href="@about/index.html" aria-label="Explore Rinehart History"><img src="@assets/rinehart-history.jpg" alt="Rinehart History, Vintage And Modern Tanker Trucks" width="1024" height="254" loading="lazy" decoding="async"></a></div></div></section>'''
    transport = intro('FOR-HIRE FUEL HAULING', 'Fuel Transport.', 'Your fuel. Your customers. Our focus is getting the load where it needs to go.')+'''<section class="transport-section"><div class="transport-capabilities"><div><h2>Who We Haul For</h2><p>Wholesalers, major oil companies and retail chains.</p></div><div><h2>Coordinate Your Load</h2><p>Speak with our team about the product, pickup, destination, timing and unloading requirements for your delivery.</p></div><div><h2>Reach Our Team</h2><p>New transport inquiries: <a href="tel:+17074628811">(707) 462-8811</a><br>Dispatch: <a href="tel:+17074673313">(707) 467-3313</a></p></div></div></section><section id="fleet" class="transport-section"><div class="transport-section-heading"><div><p class="eyebrow">REAL RINEHART EQUIPMENT</p><h2>Our Fleet.</h2></div><p>Company-owned trucks and tank trailers.</p></div>'''+fleet()+'''</section><section class="transport-section"><details class="contact-disclosure"><summary>Delivery Planning &amp; Safety</summary><div class="transport-disclosure-body"><p>Every delivery starts with the details. Discuss site access, tank and unloading arrangements, product requirements and scheduling with our team before the load is arranged.</p><p>For service availability or customer onboarding documents, <a href="@contact/index.html">contact our office</a>. Dispatch hours and direct contacts are listed on the Contact page.</p></div></details></section>'''
    story = intro('FAMILY OWNED. ROAD PROVEN.', 'Our Story.', 'Founded in Ukiah in 1959. Today, Rinehart’s focus is hauling fuel for other businesses.')+'''<section class="transport-story transport-section">'''+photo('company-history.jpg', 'Owner-supplied Rinehart company history artwork showing vintage and modern tankers')+'''<div><h2>Generations Of Getting It Done.</h2><p>Robert F. Rinehart founded the business in 1959 after beginning his oil-industry career in 1953. His son Reed now owns and operates Rinehart Oil.</p><p>The work has evolved. Honesty, integrity, reliability, operational excellence and customer focus remain the principles behind the company.</p><a class="transport-text-link" href="@trucking-for-hire/index.html">Meet Today’s Transport Business</a></div></section><section class="transport-section"><details class="contact-disclosure"><summary>Read Our Company History</summary><div class="transport-disclosure-body">'''+CONTENT['history']+'''</div></details></section>'''
    careers = intro('PEOPLE BEHIND EVERY DELIVERY', 'Careers At Rinehart.', 'Interested in driving with Rinehart? Speak with our office about current opportunities and application instructions.')+'''<section class="transport-section"><div class="transport-careers-grid"><div><h2>Start With A Conversation.</h2><p>Call our office to confirm current openings, work locations, schedules and application requirements before sending personal information.</p>'''+action('tel:+17074628811', 'Call The Office: (707) 462-8811')+'''</div>'''+photo('6338-rino-truck-4-1-of-1.webp', 'Rinehart tanker trucks lined up at the yard')+'''</div><p class="transport-note">Online applications are currently unavailable. Contact the office for the current submission method.</p><details class="contact-disclosure"><summary>Driver Qualifications &amp; Application PDF</summary><div class="transport-disclosure-body"><p>Confirm current requirements with the office. The existing driver qualification checklist includes:</p><ul><li>At least 21 years old.</li><li>A Class A CDL with tanker and hazardous materials endorsements.</li><li>At least one year of Class A driving experience.</li><li>Availability to obtain a TWIC card and TSA clearance.</li><li>A clean DMV report: 0 points in the past 12 months, or no more than 1.5 points in the past 3 years.</li><li>Pass a DOT drug test and a road test.</li><li>Perform lifting duties involving 60–80 lbs., with or without reasonable accommodation.</li><li>Willingness to work nights, weekends and holidays on a rotating schedule.</li><li>Work cooperatively with others.</li></ul><a class="transport-text-link" href="@assets/13571-driver-application-with-desc-2019-rev.pdf">Download Driver Application PDF</a><p>Call the office for current submission instructions. Do not send sensitive identification information to an unconfirmed recipient.</p></div></details></section>'''
    contact = intro('SPEAK WITH THE PEOPLE BEHIND THE DELIVERY', 'Contact &amp; Dispatch.', 'Speak directly with the team that keeps Rinehart moving to streamline your next delivery.')+'''<section class="transport-section transport-contact-actions" aria-label="Contact Rinehart"><div><h2>Dispatch</h2>'''+action('tel:+17074673313', 'Call (707) 467-3313')+action('mailto:dispatch@rinehartoil.com', 'Email Dispatch')+'''</div><div><h2>Office &amp; Transport Inquiries</h2><a class="transport-button office-call-choice office-image-button" href="#office-call-options">Choose An Office Number</a><div class="office-call-options" id="office-call-options"><h2 id="office-call-title">Choose A Number</h2><a class="office-call-choice" href="tel:+17074628811"><span>Main Office</span><strong>(707) 462-8811</strong></a><a class="office-call-choice" href="tel:+18006408814"><span>Toll Free</span><strong>(800) 640-8814</strong></a></div></div></section><section class="transport-section" id="team"><h2>Find Your Contact.</h2><p>Open a department, then select a name to email.</p>'''+CONTENT['directory']+'''</section><section class="transport-section">'''+CONTENT['hours']+'''<div class="transport-address"><h2>Visit Rinehart.</h2><p>2401 N. State Street, Ukiah, CA 95482<br>Mail: P.O. Box 725, Ukiah, CA 95482</p><a class="transport-text-link" href="https://www.google.com/maps/search/?api=1&amp;query=Rinehart+Oil+2401+N+State+Street+Ukiah+CA+95482" rel="noopener noreferrer">Get Directions</a><details class="contact-disclosure transport-map"><summary>View Map &amp; Fax Numbers</summary><div class="transport-disclosure-body"><p>Fax: (707) 468-3820 / (707) 463-8787</p><iframe title="Map Of Rinehart Oil, Ukiah" loading="lazy" referrerpolicy="no-referrer" src="https://www.google.com/maps?q=Rinehart+Oil+2401+N+State+Street+Ukiah+CA+95482&amp;z=16&amp;output=embed"></iframe></div></details></div></section>'''
    cardlock = intro('EXISTING CUSTOMER SUPPORT', 'Cardlock Customer Resources.', 'Looking for help with your existing Pacific Pride account? Use the links below or contact our customer service team.')+'''<section class="transport-section"><div class="transport-cardlock-links">'''+action('https://pacificpride.com/site-locator/', 'Find A Pacific Pride Location')+'''<a class="transport-text-link" href="@assets/6333-rino-pac-credit-app-new.pdf">Cardlock Account Application PDF</a></div>'''+CONTENT['joy']+'''</section>'''
    privacy = intro('RINEHART OIL, INC.', 'Privacy Policy.', 'Information practices and contact details.')+'<section class="transport-section transport-policy">'+CONTENT['privacy']+'</section>'
    # Preserve the approved visual actions while consolidating the surrounding content.
    home = home.replace(action('@contact/index.html', 'Discuss Your Transport Needs'), art('@contact/index.html', 'put-us-to-work.jpg', 'Put Us To Work, Contact Rinehart', 'put-work-image-button'))
    home = home.replace('<a class="transport-text-link" href="@trucking-for-hire/index.html#fleet">Explore Fuel Transport &amp; Our Fleet</a>', art('@trucking-for-hire/index.html#fleet', 'check-out-our-fleet.jpg', 'Check Out Our Fleet', 'fleet-image-button'))
    story = story.replace('<a class="transport-text-link" href="@trucking-for-hire/index.html">Meet Today’s Transport Business</a>', art('@trucking-for-hire/index.html#fleet', 'check-out-our-fleet.jpg', 'Check Out Our Fleet', 'fleet-image-button'))
    careers = careers.replace(action('tel:+17074628811', 'Call The Office: (707) 462-8811'), art('tel:+17074628811', 'talk-to-rinehart.jpg', 'Talk To Rinehart, Call The Office At (707) 462-8811', 'contact-image-button'))
    start = contact.index('<section class="transport-section transport-contact-actions"')
    end = contact.index('<section class="transport-section" id="team">', start)
    office_options = '<div class="office-call-options" id="office-call-options"><h2 id="office-call-title">Choose A Number</h2><a class="office-call-choice" href="tel:+17074628811"><span>Main Office</span><strong>(707) 462-8811</strong></a><a class="office-call-choice" href="tel:+18006408814"><span>Toll Free</span><strong>(800) 640-8814</strong></a></div>'
    console = '<section class="transport-section transport-contact-actions" aria-label="Contact Rinehart">'+art('tel:+17074673313', 'call-dispatch.jpg', 'Call Dispatch At (707) 467-3313', 'dispatch-image-button')+art('#office-call-options', 'main-office.jpg', 'Main Office, Choose A Number', 'office-image-button')+art('mailto:dispatch@rinehartoil.com', 'email-dispatch.jpg', 'Email Dispatch', 'email-image-button')+office_options+'</section>'
    contact = contact[:start]+console+contact[end:]
    contact = contact.replace('</section>', art('#team', 'ask-our-team.jpg', 'Ask Our Team, Find Your Contact', 'team-image-button')+'</section>', 1)
    directions = '<a class="transport-text-link" href="https://www.google.com/maps/search/?api=1&amp;query=Rinehart+Oil+2401+N+State+Street+Ukiah+CA+95482" rel="noopener noreferrer">Get Directions</a>'
    contact = contact.replace(directions, art('https://www.google.com/maps/@?api=1&map_action=pano&pano=FfEuPfSBLQI-kpTnBH7Asw&viewpoint=39.1814271%2C-123.209538&heading=100&pitch=0&fov=80', 'directions.jpg', 'Get Directions, View Rinehart In Google Street View', 'directions-image-button'))
    cardlock = cardlock.replace(action('https://pacificpride.com/site-locator/', 'Find A Pacific Pride Location'), art('https://pacificpride.com/site-locator/', 'pacific-pride.jpg', 'Find A Pacific Pride Location', 'cardlock-locator'))
    cardlock = cardlock.replace('<a class="transport-text-link" href="@assets/6333-rino-pac-credit-app-new.pdf">Cardlock Account Application PDF</a>', art('@assets/6333-rino-pac-credit-app-new.pdf', 'credit-app.jpg', 'Cardlock Account Application PDF', 'cardlock-credit'))
    pages = [('', 'Fuel Transport', home, True), ('trucking-for-hire', 'Fuel Transport & Our Fleet', transport, True), ('about', 'Our Story', story, False), ('employment-opportunities', 'Careers', careers, False), ('contact', 'Contact & Dispatch', contact, False), ('pacific-pride-card-lock', 'Cardlock Customer Resources', cardlock, False), ('privacy-policy', 'Privacy Policy', privacy, False)]
    routes = []
    for slug, title, body, cta in pages:
        path = ROOT/slug/'index.html'
        path.parent.mkdir(parents=True, exist_ok=True)
        # Captured subpage fragments already use ../assets/. Templates use @assets/.
        path.write_text(shell(title, slug, body, cta), encoding='utf8')
        routes.append({'source': '/'+slug+'/' if slug else '/', 'target': str(path.relative_to(ROOT)).replace('\\','/'), 'disposition': 'retained; transport-first compact preview'})
    redirects = {'fleet': 'trucking-for-hire/index.html#fleet', 'branded-fuels': 'trucking-for-hire/index.html', 'unbranded-fuels': 'trucking-for-hire/index.html', 'credit-application': 'contact/index.html', 'customer-resources': 'contact/index.html', 'resource-links': 'trucking-for-hire/index.html', 'employment-application': 'employment-opportunities/index.html', 'employment-application/office-positions': 'employment-opportunities/index.html', 'employment-application/rroi-webpagecontentdriver-application-with-desc-2019-revpdf': 'employment-opportunities/index.html', 'driver-application': 'employment-opportunities/index.html'}
    for slug, target in redirects.items():
        prefix = '../'*len(slug.split('/'))
        href = prefix+target
        path = ROOT/slug/'index.html'
        path.write_text(f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><meta http-equiv="refresh" content="0;url={href}"><title>Page Moved | Rinehart Oil</title></head><body><p>This page has moved. <a href="{href}">Continue To Rinehart</a>.</p></body></html>', encoding='utf8')
        routes.append({'source': '/'+slug+'/', 'target': str(path.relative_to(ROOT)).replace('\\','/'), 'disposition': 'redirect', 'redirectTo': target})
    (ROOT/'route-map.json').write_text(json.dumps(routes, indent=2)+'\n', encoding='utf8')
    from apply_colophon import apply
    apply(ROOT)
    from check_release_links import check
    check(ROOT)
    print('Built 7 rendered pages, including temporary Cardlock support, and 10 intentional redirects.')


if __name__ == '__main__':
    build()
